#!/usr/bin/env bash
# Pins the layer filter of `tests/verify_windows.sh`: an optional first word runs
# only the layers whose label contains it, counts the rest as skipped, and keeps
# the tally honest — the skipped count plus the run layers is the full layer
# count, and no layer is silently dropped. The full sweep costs about eight
# minutes here, so these two filtered runs (seconds each) are what make the
# per-layer re-check of a one-line edit cheap enough to actually run.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later
#
# Exit codes: 0 the filter behaves, 1 a tally disagrees,
# 125 not applicable (no gate script, or no .tools/ toolchain for it).

set -u

ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  layer filter (not inside a git checkout)\n'
    exit 125
}
cd "$ROOT" || exit 1

GATE="tests/verify_windows.sh"
[ -f "$GATE" ] || {
    printf 'SKIP  layer filter (%s missing)\n' "$GATE"
    exit 125
}
# The gate is a Windows-native script: it needs the toolchain under .tools/ that
# tests/install_windows_toolchain.sh lays down, so a Linux box has nothing to
# judge here.
[ -x ".tools/ruff/ruff.exe" ] || {
    printf 'SKIP  layer filter (no .tools/ toolchain on this box)\n'
    exit 125
}

# A private run dir: the nested gate run numbers its step files from 1, and it
# must not collide with the outer run's `.tools/.run` pair numbering.
filtered() {
    PIME_RUN_DIR=".tools/.run-filter" bash "$GATE" "$1" 2>&1
}

# One label word that names exactly one layer, and one that names none.
ONE=$(filtered 'Python lint')
NONE=$(filtered 'zzz-no-such-layer')
rm -rf .tools/.run-filter

total=$(printf '%s\n' "$NONE" | sed -n 's/^filter zzz-no-such-layer: \([0-9]\{1,\}\) layer(s) skipped$/\1/p')
one_passed=$(printf '%s\n' "$ONE" | sed -n 's/^\([0-9]\{1,\}\) passed, \([0-9]\{1,\}\) failed$/\1/p')
one_failed=$(printf '%s\n' "$ONE" | sed -n 's/^\([0-9]\{1,\}\) passed, \([0-9]\{1,\}\) failed$/\2/p')
one_skipped=$(printf '%s\n' "$ONE" | sed -n 's/^filter Python lint: \([0-9]\{1,\}\) layer(s) skipped$/\1/p')
none_passed=$(printf '%s\n' "$NONE" | sed -n 's/^\([0-9]\{1,\}\) passed, \([0-9]\{1,\}\) failed$/\1/p')

bad=0
if [ -z "$total" ] || [ "$total" -lt 1 ]; then
    printf 'unfiltered total unreadable: %s\n' "${NONE}"
    bad=1
fi
if [ "$one_failed" != "0" ]; then
    printf 'filtered run for "Python lint" did not end 0 failed: %s\n' "$one_failed"
    bad=1
fi
if [ "$one_passed" != "1" ]; then
    printf '"Python lint" should run exactly 1 layer, ran %s\n' "${one_passed:-none}"
    bad=1
fi
if [ "${one_skipped:-}" != "$((total - 1))" ]; then
    printf 'skipped %s plus 1 run is not the total %s\n' "${one_skipped:-none}" "$total"
    bad=1
fi
if [ "${none_passed:-}" != "0" ]; then
    printf 'a word matching no label still ran %s layer(s)\n' "${none_passed:-none}"
    bad=1
fi

if [ "$bad" -ne 0 ]; then
    printf 'layer filter contract broken\n'
    exit 1
fi
printf 'filter keeps %d layers: 1 run and %d skipped for "Python lint", 0 run for a miss\n' \
    "$total" "$((total - 1))"
